                num = num * 10 + int(expr[i])
                i += 1
            stack.append(num)
        else:
            if expr[i] not in variables:
                raise ValueError(f"Unknown variable: {expr[i]}")
            stack.append(variables[expr[i]])
            i += 1

    while '(' in stack:
        if stack[-1] != '(':
            raise ValueError("Mismatched parentheses")
        stack.pop()
        if len(stack) < 2:
            raise ValueError("Mismatched parentheses")
        stack.pop()
        if stack[-1] == ')':
            stack.pop()
            continue
        if stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        left = stack.pop()
        op = stack.pop()
        right = stack.pop()
        if op == '+':
            stack.append(left + right)
        elif op == '-':
            stack.append(left - right)
        elif op == '*':
            stack.append(left * right)
        elif op == '/':
            stack.append(left // right)
        else:
            raise ValueError(f"Unknown operator: {op}")

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]

