import sys
import os
import requests
import re
from typing import Dict, Any

def validate_assignment(line: str, assignments: Dict[str, Any], line_num: int) -> None:
    pattern = r'^[A-Za-z_][A-Za-z0-9_]*\s*=\s*([^=]+)$'
    match = re.fullmatch(pattern, line.strip())
    if not match:
        raise ValueError(f"Invalid assignment format on line {line_num}")

    name = match.group(1)
    expr = match.group(2)

    if name in assignments:
        raise ValueError(f"Name '{name}' already assigned on line {line_num}")

    try:
        assignments[name] = evaluate_expression(expr, assignments)
    except Exception as e:
        raise ValueError(f"Error evaluating expression on line {line_num}: {str(e)}")

def evaluate_expression(expr: str, assignments: Dict[str, Any]) -> Any:
    try:
        # Replace variable names with their values
        for name, value in assignments.items():
            expr = expr.replace(name, str(value))

        # Evaluate the expression safely
        # Using a custom eval with restricted globals and locals
        local_vars = {}
        for name, value in assignments.items():
            local_vars[name] = value

        # Replace division with floor division
        expr = re.sub(r'\s*\/\s*', '//', expr)

        # Evaluate the expression
        result = eval(expr, {'__builtins__': None}, local_vars)
        return result
    except Exception as e:
        raise ValueError(f"Expression evaluation error: {str(e)}")

def main():
    if len(sys.argv) != 2:
        print("error: missing URL argument", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    calc_token = os.getenv('CALC_TOKEN')

    try:
        headers = {'Authorization': f'Bearer {calc_token}'} if calc_token and calc_token.strip() else {}
        response = requests.get(url, headers=headers)
        response.raise_for_status()
    except Exception as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    try:
        lines = response.text.strip().split('\n')
        assignments = {}
        for line_num, line in enumerate(lines, 1):
            if not line.strip():
                continue
            validate_assignment(line, assignments, line_num)

            name = next(iter(assignments))
            value = assignments[name]
            print(f"{name}: {value}")
    except ValueError as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
